<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { showFailToast, showSuccessToast } from 'vant';
import { useRoute, useRouter } from 'vue-router';
import { api, deleteWorkspaceImage, type ProductGroupTemplate, uploadWorkspaceImage } from '../api';
import { useWorkspaceStore } from '../stores/workspace';

type Variant = { id?: string; name: string; referencePrice: string };
type FormImage = { assetId: string; url: string | null; status: 'ready' | 'uploading' | 'error'; file?: File; persisted: boolean };
type ProductGroup = { id: string; name: string; description: string | null; images: Array<{ assetId: string; url: string | null }>; variants: Array<{ id: string; name: string | null; referencePrice: string | null }> };
const route = useRoute(); const router = useRouter(); const store = useWorkspaceStore();
const editing = computed(() => typeof route.params.id === 'string'); const groupId = computed(() => String(route.params.id));
const name = ref(''); const description = ref(''); const variants = ref<Variant[]>([]); const saving = ref(false); const loading = ref(editing.value); const error = ref(''); const showTemplatePicker = ref(false); const templates = ref<ProductGroupTemplate[]>([]); const templateLoading = ref(false); const images = ref<FormImage[]>([]); const fileInput = ref<HTMLInputElement>(); const showImageRemove = ref(false); const pendingImageRemove = ref<FormImage | null>(null);
const templateOptions = computed(() => templates.value.map((item) => ({ text: item.name, value: item.id })));
const readyAssetIds = computed(() => images.value.filter((image) => image.status === 'ready').map((image) => image.assetId));
const hasUploading = computed(() => images.value.some((image) => image.status === 'uploading'));
function addVariant() { variants.value.push({ name: '', referencePrice: '' }); }
function removeVariant(index: number) { variants.value.splice(index, 1); }
function back() { void router.push(editing.value ? `/product-groups/${groupId.value}` : '/products'); }
async function loadTemplates() { if (!store.selectedWorkspaceId) return; templateLoading.value = true; try { templates.value = (await api.get<ProductGroupTemplate[]>(`/workspaces/${store.selectedWorkspaceId}/product-group-templates`)).data; } catch { showFailToast('组合模板加载失败，请稍后重试'); } finally { templateLoading.value = false; } }
async function load() { if (!editing.value || !store.selectedWorkspaceId) return; loading.value = true; error.value = ''; try { const groups = (await api.get<ProductGroup[]>(`/workspaces/${store.selectedWorkspaceId}/product-groups`)).data; const group = groups.find((item) => item.id === groupId.value); if (!group) { error.value = '商品组不存在或已删除'; return; } name.value = group.name; description.value = group.description ?? ''; variants.value = group.variants.filter((item) => item.name !== null).map((item) => ({ id: item.id, name: item.name ?? '', referencePrice: item.referencePrice ?? '' })); images.value = group.images.map((image) => ({ ...image, status: 'ready', persisted: true })); } catch { error.value = '商品组资料加载失败，请返回后重试'; } finally { loading.value = false; } }
function chooseTemplate({ selectedOptions }: { selectedOptions: Array<{ value?: string }> }) { const template = templates.value.find((item) => item.id === selectedOptions[0]?.value); showTemplatePicker.value = false; if (!template) return; const existing = new Set(variants.value.map((item) => item.name.toLocaleLowerCase())); const added = template.variants.map((item) => item.name).filter((item) => !existing.has(item.toLocaleLowerCase())).map((item) => ({ name: item, referencePrice: '' })); variants.value.push(...added); showSuccessToast(added.length ? `已添加 ${added.length} 个款式` : '款式已存在'); }
async function addFiles(files: FileList | null) { if (!files || !store.selectedWorkspaceId) return; const selected = Array.from(files).slice(0, 5 - images.value.length); if (selected.length < files.length) showFailToast('每个商品组最多上传 5 张图片'); for (const file of selected) { const temporary: FormImage = { assetId: '', url: URL.createObjectURL(file), status: 'uploading', file, persisted: false }; images.value.push(temporary); const image = images.value[images.value.length - 1]!; try { const uploaded = await uploadWorkspaceImage(store.selectedWorkspaceId, file, (assetId) => { image.assetId = assetId; }); Object.assign(image, { assetId: uploaded.assetId, url: uploaded.url, status: 'ready' }); } catch { image.status = 'error'; showFailToast(`“${file.name}”上传失败，可移除后重试`); } } if (fileInput.value) fileInput.value.value = ''; }
function requestImageRemove(image: FormImage) { pendingImageRemove.value = image; showImageRemove.value = true; }
function removeFailedImage(image: FormImage) { images.value = images.value.filter((item) => item !== image); if (image.url?.startsWith('blob:')) URL.revokeObjectURL(image.url); }
async function confirmImageRemove() { const image = pendingImageRemove.value; if (!image) return; images.value = images.value.filter((item) => item !== image); showImageRemove.value = false; pendingImageRemove.value = null; if (!image.persisted && image.status === 'ready' && image.assetId && store.selectedWorkspaceId) { try { await deleteWorkspaceImage(store.selectedWorkspaceId, image.assetId); } catch { /* 资源会由服务端后续清理。 */ } } if (image.url?.startsWith('blob:')) URL.revokeObjectURL(image.url); }
async function save() { if (!store.selectedWorkspaceId || !name.value.trim()) return showFailToast('请填写商品组名称'); if (hasUploading.value) return showFailToast('图片仍在上传中，请稍候'); if (images.value.some((image) => image.status === 'error')) return showFailToast('请移除上传失败的图片'); if (variants.value.some((item) => !item.name.trim() || (item.referencePrice && !/^\d+(\.\d{1,2})?$/.test(item.referencePrice)))) return showFailToast('请填写有效的款式和参考价'); saving.value = true; const payload = { name: name.value.trim(), description: description.value.trim() || null, assetIds: readyAssetIds.value, variants: variants.value.map((item) => ({ ...(item.id ? { id: item.id } : {}), name: item.name.trim(), referencePrice: item.referencePrice || null })) }; try { if (editing.value) { await api.patch(`/workspaces/${store.selectedWorkspaceId}/product-groups/${groupId.value}`, payload); showSuccessToast('商品组已保存'); await router.replace(`/product-groups/${groupId.value}`); } else { await api.post(`/workspaces/${store.selectedWorkspaceId}/product-groups`, payload); showSuccessToast('商品组已保存'); await router.replace('/products'); } } catch (requestError: unknown) { showFailToast((requestError as { response?: { data?: { message?: string } } }).response?.data?.message || '保存失败'); } finally { saving.value = false; } }
onMounted(async () => { if (!store.workspaces.length) await store.load(); if (!store.canEditProducts) { error.value = '当前角色没有编辑商品权限'; loading.value = false; return; } await Promise.all([loadTemplates(), load()]); });
</script>
<template><div class="group-form" data-ai-id="product-group-form-page"><van-nav-bar :title="editing ? '编辑商品组' : '新建商品组'" left-text="返回" left-arrow @click-left="back"/><div v-if="loading" class="state"><van-loading>正在加载商品组…</van-loading></div><van-empty v-else-if="error" :description="error"><van-button type="primary" size="small" @click="back">返回</van-button></van-empty><main v-else><p class="note">商品组用于归并同一套商品；修改资料不会改动已发生采购、上架、销售或结算的名称。</p><van-field v-model="name" label="商品组名称" required placeholder="例如：专辑 A 小卡" data-ai-id="product-group-name"/><van-field v-model="description" label="描述" type="textarea" rows="3" placeholder="可选" data-ai-id="product-group-description"/><section class="image-section" data-ai-id="product-group-image-section"><div class="image-head"><div><strong>商品组图片</strong><small>最多 5 张，第一张显示在商品列表</small></div><van-button plain size="small" :disabled="images.length >= 5" data-ai-id="product-group-image-add" @click="fileInput?.click()">{{ images.length >= 5 ? '最多 5 张' : '添加图片' }}</van-button></div><input ref="fileInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden data-ai-id="product-group-image-input" @change="addFiles(($event.target as HTMLInputElement).files)"><div v-if="!images.length" class="image-empty" data-ai-id="product-group-image-list">暂无图片</div><div v-else class="image-grid" data-ai-id="product-group-image-list"><article v-for="(image,index) in images" :key="`${image.assetId}-${index}`" class="image-item" :data-ai-id="image.status === 'ready' ? `product-group-image-item-${image.assetId}` : image.status === 'uploading' ? 'product-group-image-uploading' : `product-group-image-upload-error-${index}`"><template v-if="image.status === 'ready'"><img :src="image.url || ''" alt="商品组图片"><span v-if="index === 0" class="cover-badge">首图</span><button type="button" :data-ai-id="`product-group-image-remove-${image.assetId}`" aria-label="移除图片" title="移除图片" @click="requestImageRemove(image)"><van-icon name="delete-o"/></button></template><template v-else-if="image.status === 'uploading'"><span>图片上传中…</span></template><div v-else class="upload-error"><span>上传失败</span><button type="button" :data-ai-id="`product-group-image-remove-error-${index}`" @click="removeFailedImage(image)">移除</button></div></article></div></section><section data-ai-id="product-group-variants"><div class="head"><div><h2>款式（可选）</h2><small>每款可单独填写参考价；已有业务记录的款式不能移除。</small></div><van-button plain size="small" type="primary" data-ai-id="product-group-template-manage" @click="router.push('/product-group-templates')">组合模板管理</van-button></div><van-button block plain type="primary" :loading="templateLoading" data-ai-id="product-group-template-generate" @click="showTemplatePicker = true">快捷生成商品组</van-button><div class="variant-add"><van-button plain type="primary" data-ai-id="product-group-add-variant" @click="addVariant">新增款式</van-button></div><div class="variant-list"><div v-for="(variant,index) in variants" :key="variant.id ?? `new-${index}`" class="variant" :data-ai-id="`product-group-variant-${index}`"><div class="variant-fields"><van-field v-model="variant.name" label="款式名称" required placeholder="例如：樱" :data-ai-id="`product-group-variant-name-${index}`"/><van-field v-model="variant.referencePrice" label="参考价格（元）" inputmode="decimal" placeholder="可选，例如 99.9" :data-ai-id="`product-group-variant-price-${index}`"/></div><button type="button" class="variant-remove" :data-ai-id="`product-group-variant-remove-${index}`" aria-label="移除款式" title="移除款式" @click="removeVariant(index)"><van-icon name="delete-o"/></button></div></div></section></main><footer v-if="!loading&&!error" data-ai-id="product-group-actions"><van-button block type="primary" :loading="saving" data-ai-id="product-group-save" @click="save">{{ editing ? '保存修改' : '保存商品组' }}</van-button></footer></div><van-popup v-model:show="showTemplatePicker" position="bottom" round data-ai-id="product-group-template-picker"><van-picker v-if="templateOptions.length" title="选择组合模板" :columns="templateOptions" @confirm="chooseTemplate" @cancel="showTemplatePicker=false"/><van-empty v-else description="还没有组合模板"><van-button type="primary" size="small" @click="router.push('/product-group-templates')">去管理</van-button></van-empty></van-popup><van-popup v-model:show="showImageRemove" class="confirm-popup" round data-ai-id="product-group-image-remove-confirm"><section><h2>移除这张图片？</h2><p>保存后，图片将不再属于该商品组。</p><footer><van-button @click="showImageRemove=false">保留图片</van-button><van-button type="danger" @click="confirmImageRemove">移除图片</van-button></footer></section></van-popup></template>
<style scoped>.group-form{min-height:100vh;padding-bottom:84px;background:#f5f7fb}.group-form :deep(.van-nav-bar){position:sticky;top:0;z-index:2}.group-form main{padding:16px}.state{display:grid;min-height:60vh;place-items:center}.note{margin:0 0 12px;color:#71809a;font-size:13px;line-height:1.5}.group-form :deep(.van-field),section{margin-bottom:12px;border-radius:10px;background:#fff}.head,.image-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:12px}.head h2,.head small,.image-head strong,.image-head small{display:block}.head h2{margin:0;font-size:17px}.head small,.image-head small{margin-top:4px;color:#71809a;font-size:12px;line-height:1.5}.head :deep(.van-button),.image-head :deep(.van-button){flex:0 0 auto;min-height:36px}.group-form section> :deep(.van-button){margin-bottom:10px}.variant-add :deep(.van-button){width:100%;min-height:40px}.variant-list{display:grid;gap:12px;margin-top:12px}.variant{display:grid;grid-template-columns:minmax(0,1fr) 44px;gap:8px;align-items:center;padding:10px;border:1px solid #dce2ee;border-radius:8px}.variant-fields{display:grid;gap:8px}.variant :deep(.van-field){margin:0;border:0;background:#f5f7fb}.variant :deep(.van-field__label){width:116px}.variant-remove{display:grid;width:44px;min-height:44px;place-items:center;border:0;background:transparent;color:#b42318;font-size:20px}.group-form section{padding:14px}.image-empty{display:grid;min-height:104px;place-items:center;border:1px dashed #b5c0d7;border-radius:9px;color:#7b879a;font-size:13px}.image-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.image-item{position:relative;display:grid;min-height:102px;place-items:center;overflow:hidden;border:1px solid #e4e8f0;border-radius:9px;background:#edf1f7;color:#536078;font-size:12px;text-align:center}.image-item img{width:100%;height:102px;object-fit:cover}.image-item>button{position:absolute;right:3px;bottom:3px;display:grid;width:32px;height:32px;place-items:center;border:0;border-radius:6px;background:#fffb;color:#b42318;font-size:18px}.upload-error{display:grid;place-items:center;gap:6px}.upload-error button{min-height:32px;padding:0 12px;border:0;border-radius:6px;background:#fff;color:#b42318;font-size:12px}.cover-badge{position:absolute;top:5px;left:5px;padding:2px 5px;border-radius:4px;background:#172033cc;color:#fff;font-size:10px;font-weight:700}.confirm-popup{width:calc(100% - 40px);max-width:360px}.confirm-popup section{padding:20px}.confirm-popup h2{margin:0 0 8px;font-size:18px}.confirm-popup p{margin:0;color:#536078;font-size:13px}.confirm-popup footer{position:static;display:flex;justify-content:flex-end;gap:8px;margin-top:20px;padding:0;border:0;background:transparent}.confirm-popup footer :deep(.van-button){min-height:40px}footer{position:fixed;right:0;bottom:0;left:0;z-index:3;max-width:430px;margin:auto;padding:12px 16px calc(12px + env(safe-area-inset-bottom));border-top:1px solid #e4e8f0;background:#fff}footer :deep(.van-button){min-height:44px}</style>
